+/** Returns the count if it is a valid token count, otherwise 0 (e.g. when a provider omits it) */
+function toTokenCount(value: unknown): number {
+	return typeof value === 'number' && Number.isFinite(value) ? value : 0;
+}
+
 export function accumulateTokenUsage(
 	context: IExecuteFunctions,
-	inputTokens: number,
-	outputTokens: number,
+	inputTokens: number | null | undefined,
+	outputTokens: number | null | undefined,
 ): void {
 	const prev = context.getExecuteData()?.metadata?.tokenUsage;
 	context.setMetadata({
 		tokenUsage: {
-			inputTokens: (prev?.inputTokens ?? 0) + inputTokens,
-			outputTokens: (prev?.outputTokens ?? 0) + outputTokens,
+			inputTokens: toTokenCount(prev?.inputTokens) + toTokenCount(inputTokens),
+			outputTokens: toTokenCount(prev?.outputTokens) + toTokenCount(outputTokens),
 		},
 	});
 }
